namespace {
std::vector<std::pair<const char*, std::function<void()>>>& registry() {
    static std::vector<std::pair<const char*, std::function<void()>>> r;
    return r;
}
int failures = 0;
struct Registrar {
    Registrar(const char* name, std::function<void()> fn) { registry().emplace_back(name, std::move(fn)); }
};
}

// Generated by CMake in <build>/generated/iki_demo_objects.cpp (see cmake/Games.cmake).
void mush2dLinkGame_iki_demo();

#define CHECK(expr) do { if (!(expr)) { std::printf("  CHECK failed: %s (%s:%d)\n", #expr, __FILE__, __LINE__); ++failures; } } while (0)
#define TEST(name) static void name(); static Registrar reg_##name(#name, name); static void name()

namespace {
// Calls f and reports whether it threw an exception whose message contains text.
bool throwsWith(const std::function<void()>& f, const std::string& text) {
    try {
        f();
    } catch (const std::exception& e) {
        return std::string(e.what()).find(text) != std::string::npos;
    }
    return false; // nothing was thrown
}
}

